/* cppi::ea0fc24bbc350a0212c85feb2e1ee52a920a71f2af622dc400b965545b492e31 */
/* QuickSight faf2d053-dd2d-45f7-94e2-209243022895 */
SELECT "business_date", "year", "from_currency", "to_currency", "rate_type_code", "source", "bid_price", "ask_price", "mid_price", "factor", "inverse_quoted", "last_update_date", "vendor_file_name", "arrival_time"
FROM (SELECT *
FROM market.refinitiv_exchange_rates_wmr) AS "FX Rates - EUR, GBP, USD (PROD)"

/* cppi::219c8d1d5241c0039733774d8699c58754e2ac4684ab8cb51f09cd0aea42f319 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-20' and end_date = '2025-05-20')
and start_date = '2025-05-20' and end_date = '2025-05-20'

/* cppi::af843a2c54373367290ced057d7abf7b839e1f70e85946494c7447ab8db9928d */
